from app.database.crud import (
    create_new_letter,
    create_triage_request,
    retrieve_patient_by_email,
    retrieve_user_by_email,
)
from app.utils.create_letter_utils import (
    format_address,
)


def insert_welcome_consent_letter(users_name: str, user_email: str, practice_address: str):
    formatted_address_html = format_address(practice_address)
    letter = f"""
	<table><tbody><tr><td colspan="1" rowspan="1"><p><div style="display: flex; position: relative; max-width: 3vw"><p><img style="width: 100%; height: 100%;" src="data:image/png;base64,"></p></div></p></td><td colspan="3" rowspan="1">{formatted_address_html}</td></tr></tbody></table><p></p><p></p><p>Dear {users_name}</p><p></p><p></p><p><strong>Welcome to indentr!</strong></p><p></p><p></p><p style="text-align: start">We are thrilled to have you join our community of dental professionals dedicated to revolutionising the dental industry through the power of artificial intelligence. Your decision to partner with us marks the beginning of an exciting journey towards streamlining workflows, enhancing patient care, and embracing innovation like never before.</p><p style="text-align: start"></p><p style="text-align: start">At indentr, we are passionate about leveraging cutting-edge technology to simplify your day-to-day operations and empower you to focus on what matters most – delivering exceptional dental care to your patients. Whether it's generating AI-driven consent letters or revolutionising audio note-taking, our goal is to provide you with the tools and resources you need to thrive in today's dynamic dental landscape.</p><p style="text-align: start"></p><p style="text-align: start">As you embark on this journey with us, know that you are not alone. Our dedicated team is here to support you every step of the way, offering guidance, expertise, and unparalleled customer service to ensure your experience with indentr is nothing short of exceptional. If you have any questions, queries or concerns then please don't hesitate to contact the team at support@indentr.com, we are here to help every step of the way. </p><p style="text-align: start"></p><p style="text-align: start">Make sure to check your inbox as we've sent you some instructions on how to get set up properly and make the most of our services. We want to ensure you have everything you need to get started smoothly and use our tools effectively. </p><p style="text-align: start"></p><p style="text-align: start">Once again, welcome to the indentr family! We are excited to collaborate with you, learn from you, and together, shape the future of dentistry.</p><p style="text-align: start"></p><p style="text-align: start">Warm regards,</p><p style="text-align: start"></p><p style="text-align: start">The indentr team</p>
	"""
    user = retrieve_user_by_email(user_email)
    patient = retrieve_patient_by_email("welcomeletter@indentr.com")
    create_new_letter(user["_id"], letter, patient["_id"])


def insert_instruction_triages(practice_id):
    create_triage_request(practice_id=practice_id, email="instructions@indentr.com", diagnosis="Triage: instructions and set up", instruction=True)
    create_triage_request(
        practice_id=practice_id, email="instructions@indentr.com", diagnosis="Audio note: instructions and walkthrough", instruction=True
    )
    create_triage_request(
        practice_id=practice_id, email="instructions@indentr.com", diagnosis="Consent letter: instructions and guidance", instruction=True
    )
